function validate([happiness, k]) {
  if (!Array.isArray(happiness) || happiness.length < 1 || happiness.length > 200000) return 'happiness needs 1 to 2 * 10^5 values.';
  if (happiness.some(v => !Number.isInteger(v) || v < 1 || v > 100000000)) return 'Each happiness value is an integer from 1 to 10^8.';
  if (!Number.isInteger(k) || k < 1 || k > happiness.length) return 'k is between 1 and the number of children.';
  return null;
}

