function maximumHappinessSum(happiness, k) {
  happiness.sort((a, b) => b - a);
  let total = 0;

  for (let i = 0; i < k; i++) {
    const value = happiness[i] - i;
    if (value <= 0) {
      break;
    }
    total += value;
  }
  return total;
}

