function maximumHappinessSum(happiness, k) {
  const n = happiness.length;
  const used = new Array(n).fill(false);
  const search = (turn) => {
    if (turn === k) return 0;
    let best = 0;
    for (let c = 0; c < n; c++) {
      if (used[c]) continue;
      used[c] = true;
      best = Math.max(best, Math.max(happiness[c] - turn, 0) + search(turn + 1));
      used[c] = false;
    }
    return best;
  };
  return search(0);
}

